package com.oasis.reservation.ui;
import com.oasis.reservation.service.AuthService;import com.oasis.reservation.util.Theme;import javax.swing.*;import java.awt.*;
public class LoginFrame extends JFrame{
 private final JTextField user=new JTextField("admin"); private final JPasswordField pass=new JPasswordField("admin123");
 public LoginFrame(){setTitle("RailReserve • Sign In");setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);setSize(920,620);setMinimumSize(new Dimension(760,520));setLocationRelativeTo(null);build();}
 private void build(){JPanel root=new JPanel(new GridLayout(1,2));root.setBackground(Theme.CLOUD);
  JPanel hero=new JPanel(new BorderLayout());hero.setBackground(Theme.NAVY);hero.setBorder(BorderFactory.createEmptyBorder(55,55,55,45));
  JPanel ht=new JPanel();ht.setOpaque(false);ht.setLayout(new BoxLayout(ht,BoxLayout.Y_AXIS));JLabel logo=Theme.heading("RAILRESERVE",30);logo.setForeground(Color.WHITE);ht.add(logo);ht.add(Box.createVerticalStrut(18));JLabel t=Theme.heading("Your journey,\n beautifully organised.",34);t.setForeground(Color.WHITE);ht.add(t);ht.add(Box.createVerticalStrut(18));JLabel d=Theme.body("Reserve tickets, explore train information,\nand check live running status from one place.");d.setForeground(Color.decode("#dbe9f5"));ht.add(d);hero.add(ht,BorderLayout.NORTH);JLabel foot=Theme.body("Oasis Infobyte • Java Development Internship");foot.setForeground(Color.decode("#b9cfe1"));hero.add(foot,BorderLayout.SOUTH);
  JPanel right=new JPanel(new GridBagLayout());right.setBackground(Theme.CLOUD);JPanel card=Theme.card();card.setPreferredSize(new Dimension(390,390));card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.add(Theme.heading("Welcome back",27));card.add(Box.createVerticalStrut(7));card.add(Theme.body("Sign in to continue to RailReserve"));card.add(Box.createVerticalStrut(28));card.add(Theme.body("Username"));card.add(Box.createVerticalStrut(7));Theme.styleField(user);card.add(user);card.add(Box.createVerticalStrut(16));card.add(Theme.body("Password"));card.add(Box.createVerticalStrut(7));card.add(pass);card.add(Box.createVerticalStrut(24));JButton b=Theme.primaryButton("Sign In");b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,46));b.addActionListener(e->login());card.add(b);card.add(Box.createVerticalStrut(16));JLabel demo=Theme.body("Demo account  •  admin / admin123");demo.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(demo);right.add(card);root.add(hero);root.add(right);setContentPane(root);}
 private void login(){try{if(new AuthService().login(user.getText().trim(),new String(pass.getPassword()))!=null){dispose();new MainFrame(user.getText().trim()).setVisible(true);}else JOptionPane.showMessageDialog(this,"Invalid username or password.","Sign in failed",JOptionPane.WARNING_MESSAGE);}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Sign in failed",JOptionPane.ERROR_MESSAGE);}}
}
